export function LineChart({title, subtitle, labels, series, formatValue = defaultFmt}: LineChartProps) {
  const [hover, setHover] = useState<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const n = labels.length;
  const maxValue = Math.max(...series.flatMap(s => s.values));
  const ticks = useMemo(() => niceTicks(maxValue), [maxValue]);
  const yMax = ticks[ticks.length - 1];
  const x = (i: number) => PAD.left + (PLOT_W * i) / (n - 1);
  const y = (v: number) => PAD.top + PLOT_H * (1 - v / yMax);

  const paths = series.map(s => s.values.map((v, i) => `${i === 0 ? 'M' : 'L'}${x(i).toFixed(2)},${y(v).toFixed(2)}`).join(' '));

  const handlePointerMove = (e: React.PointerEvent<SVGRectElement>) => {
    const rect = e.currentTarget.closest('svg')!.getBoundingClientRect();
    const px = ((e.clientX - rect.left) / rect.width) * W;
    const i = Math.round(((px - PAD.left) / PLOT_W) * (n - 1));
    setHover(Math.max(0, Math.min(n - 1, i)));
  };

