import {useMemo, useRef, useState} from 'react';
import type {KeyboardEvent, PointerEvent} from 'react';

export interface LineChartSeries {
    name: string;
    values: number[];
}

export interface LineChartProps {
    title: string;
    subtitle?: string;
    labels: string[];
    series: LineChartSeries[];
    formatValue?: (value: number) => string;
}

const W = 720;
const H = 372;
const PAD = {top: 20, right: 60, bottom: 36, left: 48};
const PLOT_W = W - PAD.left - PAD.right;
const PLOT_H = H - PAD.top - PAD.bottom;

// Categorical slots 1–2 of the validated palette, per mode (see app.css:
// .viz-root / .g-root_theme_dark .viz-root define --viz-series-*).
const SERIES_COLORS = ['var(--viz-series-1)', 'var(--viz-series-2)'];
const SURFACE = 'var(--g-color-base-float)';

const defaultFormat = new Intl.NumberFormat('ru-RU', {maximumFractionDigits: 0});

function niceTicks(maxValue: number, desired = 4): number[] {
    if (!(maxValue > 0)) return [0, 1];
    const raw = maxValue / desired;
    const mag = 10 ** Math.floor(Math.log10(raw));
    const norm = raw / mag;
    const step = (norm <= 1 ? 1 : norm <= 2 ? 2 : norm <= 2.5 ? 2.5 : norm <= 5 ? 5 : 10) * mag;
    const niceMax = Math.ceil(maxValue / step) * step;
    const ticks: number[] = [];
    for (let v = 0; v <= niceMax + 1e-9; v += step) ticks.push(Math.round(v * 1e6) / 1e6);
    return ticks;
}
