/* ── Палитра серий: валидированные ступени (слоты 1–2) под каждую тему.
      Хром (текст, сетка, поверхности) берётся из токенов Gravity UI
      (--g-color-*), которые сами переключаются классом .g-root_theme_*. ── */
.viz-root {
    --viz-series-1: #2a78d6; /* blue  — light */
    --viz-series-2: #eb6834; /* orange — light */
}

.g-root_theme_dark .viz-root {
    --viz-series-1: #3987e5; /* blue  — dark */
    --viz-series-2: #d95926; /* orange — dark */
}

body {
    margin: 0;
}

.page {
    min-height: 100vh;
    background: var(--g-color-base-background);
    color: var(--g-color-text-primary);
    transition:
        background-color 0.2s ease,
        color 0.2s ease;
}

.page-inner {
    max-width: 860px;
    margin: 0 auto;
    padding: 32px 24px 48px;
}

.page-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 16px;
    margin-bottom: 20px;
}

.page-subtitle {
    margin-top: 4px;
}

.chart-card {
    background: var(--g-color-base-float);
    border: 1px solid var(--g-color-line-generic);
    border-radius: 16px;
    padding: 20px 24px 12px;
    transition:
        background-color 0.2s ease,
        border-color 0.2s ease;
}

/* ── График ── */

.viz-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 8px 16px;
    margin-bottom: 12px;
}

.viz-title {
    font-size: 15px;
    font-weight: 600;
    color: var(--g-color-text-primary);
}

.viz-subtitle {
    margin-top: 2px;
    font-size: 13px;
    color: var(--g-color-text-secondary);
}

.viz-legend {
    display: flex;
    gap: 20px;
}

.viz-legend-item {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
    color: var(--g-color-text-primary);
}

.viz-chart {
    position: relative;
    outline: none;
    border-radius: 8px;
}

.viz-chart:focus-visible {
    outline: 2px solid var(--g-color-line-brand);
    outline-offset: 4px;
}

.viz-svg {
    display: block;
    width: 100%;
    height: auto;
}

.viz-grid {
    stroke: var(--g-color-line-generic);
    stroke-width: 1;
}

.viz-tick-text {
    fill: var(--g-color-text-hint);
    font-size: 11px;
    font-variant-numeric: tabular-nums;
}

.viz-end-label {
    fill: var(--g-color-text-primary);
    font-size: 12px;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
}

.viz-line {
    fill: none;
    stroke-width: 2;
    stroke-linejoin: round;
    stroke-linecap: round;
}

.viz-tooltip {
    position: absolute;
    z-index: 2;
    min-width: 140px;
    padding: 8px 10px;
    pointer-events: none;
    background: var(--g-color-base-float);
    border: 1px solid var(--g-color-line-generic);
    border-radius: 10px;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.14);
    font-size: 13px;
}

.viz-tooltip-title {
    margin-bottom: 4px;
    color: var(--g-color-text-secondary);
}

.viz-tooltip-row {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 2px 0;
}

.viz-tooltip-row strong {
    color: var(--g-color-text-primary);
    font-variant-numeric: tabular-nums;
}

.viz-tooltip-name {
    color: var(--g-color-text-secondary);
}

/* ── Табличное представление ── */

.viz-table {
    margin-top: 8px;
}

.viz-table summary {
    cursor: pointer;
    font-size: 13px;
    color: var(--g-color-text-secondary);
}

.viz-table summary:hover {
    color: var(--g-color-text-primary);
}

.viz-table table {
    width: 100%;
    margin-top: 8px;
    border-collapse: collapse;
    font-size: 13px;
}

.viz-table th,
.viz-table td {
    padding: 6px 12px;
    border-bottom: 1px solid var(--g-color-line-generic);
    text-align: left;
}

.viz-table thead th {
    font-weight: 500;
    color: var(--g-color-text-secondary);
}

.viz-table tbody th {
    font-weight: 400;
    color: var(--g-color-text-primary);
}

.viz-table td {
    color: var(--g-color-text-primary);
}

.viz-table .num {
    text-align: right;
    font-variant-numeric: tabular-nums;
}

