mkdir -p /tmp/ssr-check && cat > /tmp/ssr-check/entry.tsx <<'EOF'
import * as React from 'react';
import {renderToString} from 'react-dom/server';
import {App} from '/home/sandbox/workspace/src/App';

const html = renderToString(React.createElement(App));
console.log('HTML_LEN', html.length);
const checks: [string, boolean][] = [
    ['scoped dark-capable root class present', /g-root_theme_light/.test(html)],
    ['svg chart rendered', /viz-svg/.test(html)],
    ['legend with both series', /Выручка/.test(html) && /Расходы/.test(html)],
    ['line paths drawn', (html.match(/class="viz-line"/g) || []).length === 2],
    ['end labels 66 and 43', />66</.test(html) && />43</.test(html)],
    ['y ticks 0..80', />80</.test(html) && />40</.test(html)],
    ['series colors via CSS vars', html.includes('var(--viz-series-1)') && html.includes('var(--viz-series-2)')],
    ['surface ring on end dots', html.includes('var(--g-color-base-float)')],
    ['table view present', /Данные таблицей/.test(html) && /<table/.test(html)],
    ['hit rect present', /fill="transparent"/.test(html)],
    ['keyboard focusable chart', /tabindex="0"|tabIndex/.test(html)],
];
let ok = true;
for (const [name, pass] of checks) { console.log(pass ? 'PASS' : 'FAIL', name); if (!pass) ok = false; }
const m = html.match(/class="viz-line"[^>]*d="([^"]+)"/);
console.log('FIRST_PATH', m ? m[1].slice(0, 120) : 'none');
process.exit(ok ? 0 : 1);
EOF
